const situationKind=root.querySelector('[name=situationKind]');if(situationKind)situationKind.onchange=async()=>{try{await saveCue();render();}catch{}};const breakLayout=root.querySelector('[name=breakLayout]');if(breakLayout)breakLayout.onchange=async()=>{try{await saveCue();render();}catch{}};root.querySelectorAll('[data-conversion-result]').forEach(button=>button.onclick=async()=>{const distance=Number(state.game.distance);if(!Number.isFinite(distance)||distance<0||distance>100||String(state.game.distance).trim()===''){toast('Set a numeric distance on the scorebug before recording the attempt.',true);return;}try{await saveCue();const c=state.preview;await act('preview',{attempts:Number(c.attempts||0)+1,conversions:Number(c.conversions||0)+(button.dataset.conversionResult==='made'?1:0),conversionDistances:[...(c.conversionDistances||[]),distance]});render();}catch{}});const cuePlayer=$('#cue-player');if(cuePlayer)cuePlayer.onchange=e=>safe('preview',{playerId:e.target.value});
$('#cue-form').onsubmit=async e=>{e.preventDefault();try{await saveCue();toast('Preview updated.');}catch{}};
