if($('#preview-kicker'))$('#preview-kicker').onclick=async()=>{try{await act('lineup',{team:lineupTeam,specialTeams:Object.fromEntries(new FormData($('#special-form')))});await act('preview',{type:'situation',team:lineupTeam,situationKind:'kicker',kickerId:''});tab='graphics';render();}catch{}};
